import sys

def solve():
    s = sys.stdin.readline().strip()
    try:
        line = sys.stdin.readline().strip()
        if not line:
            return
        k = int(line)
    except ValueError:
        return

    n = len(s)

    # Check if total length is divisible by k
    if n % k != 0:
        print("NO")
        return

    length = n // k

    # If length is 0, it means k > n, which is impossible for non-empty parts
    if length == 0:
        print("NO")
        return

    # Check each substring of length 'length'
    for i in range(0, n, length):
        substring = s[i:i+length]
        if substring != substring[::-1]:
            print("NO")
            return

    print("YES")

if __name__ == "__main__":
    solve()
